import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"鹜落霜洲","description":"","frontmatter":{"title":"鹜落霜洲","date":"2026-11-20T00:00:00.000Z","seq":193,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词"},"headers":[],"relativePath":"blogs/全宋词·柳永/鹜落霜洲.md","filePath":"blogs/全宋词·柳永/鹜落霜洲.md"}'),o={name:"blogs/全宋词·柳永/鹜落霜洲.md"};function l(c,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="鹜落霜洲" tabindex="-1">鹜落霜洲 <a class="header-anchor" href="#鹜落霜洲" aria-label="Permalink to &quot;鹜落霜洲&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　倾杯・倾杯乐</p><div class="poem"><p class="poem-stanza">鹜落霜洲，雁横烟渚，分明画出秋色。</p><p class="poem-stanza">暮雨乍歇。</p><p class="poem-stanza">小楫夜泊，宿苇村山驿。</p><p class="poem-stanza">何人月下临风处，起一声羌笛。</p><p class="poem-stanza">离愁万绪，闻岸草、切切蛩吟如织。</p><p class="poem-stanza">为忆。</p><p class="poem-stanza">芳容别后，水遥山远，何计凭鳞翼。</p><p class="poem-stanza">想绣阁深沈，争知憔悴损、天涯行客。</p><p class="poem-stanza">楚峡云归，高阳人散，寂寞狂踪迹。</p><p class="poem-stanza">望京国。</p><p class="poem-stanza">空目断、远峰凝碧。</p></div>',3)])])}const u=s(o,[["render",l]]);export{d as __pageData,u as default};
